(ns futon3c.diagramprover.wm-wire-producer-wm-wire-flight-cast-click-start-author-test-literal-fixture-test
  (:require [cheshire.core :as json] [clojure.edn :as edn] [clojure.java.io :as io] [clojure.test :refer [deftest is testing]] [futon2.aif.flight-runner :as fr] [futon3c.transport.http :as http] [futon3c.wm.runner-service :as service])
  (:import [java.security MessageDigest]))
(def producer 'futon3c.diagramprover.wm-wire-producer-wm-wire-flight-cast-click-start-author-test-literal-fixture-test) (def operation 'futon3c.transport.http/handle-wm-click-start) (def wire-id [:flight-cast :click-start :author])
(defn- observe [opts] (let [cast (fr/click-cast opts) captured (atom nil) body (merge {:flight-edn (pr-str {:target "M-wire" :wants []}) :run-id "wire-run" :issuing-caller "wm-flight" :trigger "duree-click-on-demand"} (into {} (filter (comp string? val)) cast)) resp (with-redefs [service/click! (fn [x] (reset! captured x) {:click-id "wire-click-1"}) service/cast-preflight-refusal (fn [_] nil)] (@#'http/handle-wm-click-start {:body (json/generate-string body)} {}))] {:writer (:author cast) :reader (:author @captured) :response-status (:status resp)}))
(defn build-record [] {:producer producer :operation operation :inputs {:seats {:author "claude-6" :reviewer "claude-13"} :cases [:primary :absent :different]} :wires {wire-id {:primary (observe {:author "claude-6" :reviewer "claude-13"}) :interventions {:absent (observe {}) :different (observe {:author "claude-13" :reviewer "claude-13"})}}} :left-out {}})
(def stem "wm-wire-flight-cast-click-start-author-test-literal-fixture")
(defn- text [x] (str (pr-str x) "\n")) (defn- sha [s] (apply str (map #(format "%02x" (bit-and % 255)) (.digest (MessageDigest/getInstance "SHA-256") (.getBytes s "UTF-8")))))
(defn- files [] (filter #(.startsWith (.getName %) (str stem "@")) (.listFiles (io/file "test/fixtures/wire-producers")))) (defn- write! [r] (let [s (text r) f (io/file "test/fixtures/wire-producers" (str stem "@" (subs (sha s) 0 12) ".edn"))] (when (.exists f) (throw (ex-info "record exists" {}))) (spit f s) (println f)))
(defn- leaves [x] (letfn [(walk [p v] (if (map? v) (mapcat (fn [[k z]] (walk (conj p k) z)) v) [p]))] (walk [] x)))
(deftest producer-test (let [a (build-record)] (if (= "1" (System/getenv "WM_WIRE_PRODUCER_WRITE")) (write! a) (let [fs (files)] (is (= 1 (count fs))) (let [e (edn/read-string (slurp (first fs)))] (doseq [p (leaves e)] (testing (pr-str p) (is (= (get-in e p) (get-in a p))))))))))
